---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier
local home = os.getenv("HOME")

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)

-- Exit/shutdown bind: fixed fallback to use a real dispatcher instead of
-- the invalid `hl.dsp.exit()` string passed through hyprctl dispatch.
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch exit"))

hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))

-- Toggle floating state of the focused window (kitty/waypaper opened via
-- the float+center rules below, so this "un-floats" them back to tiled)
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))

-- On-demand: force the focused window to float AND recenter it, regardless
-- of any window rule. Handy for apps that don't have a dedicated rule.
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("hyprctl dispatch setfloating active && hyprctl dispatch centerwindow"))

hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

--------------------------------
---- WORKspace KEYBINDINGS -----
--------------------------------

-- Switch Workspaces (AZERTY top row keys)
hl.bind(mainMod .. " + ampersand",   hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + eacute",      hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + quotedbl",    hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + apostrophe",  hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + parenleft",   hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + minus",       hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + egrave",      hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + underscore",  hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + ccedilla",    hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + agrave",      hl.dsp.focus({ workspace = 10 }))

-- Move Active Window to Workspace (AZERTY with SHIFT)
hl.bind(mainMod .. " + SHIFT + ampersand",  hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + SHIFT + eacute",     hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + SHIFT + quotedbl",   hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + SHIFT + apostrophe", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + SHIFT + parenleft",  hl.dsp.window.move({ workspace = 5 }))
hl.bind(mainMod .. " + SHIFT + minus",      hl.dsp.window.move({ workspace = 6 }))
hl.bind(mainMod .. " + SHIFT + egrave",     hl.dsp.window.move({ workspace = 7 }))
hl.bind(mainMod .. " + SHIFT + underscore", hl.dsp.window.move({ workspace = 8 }))
hl.bind(mainMod .. " + SHIFT + ccedilla",   hl.dsp.window.move({ workspace = 9 }))
hl.bind(mainMod .. " + SHIFT + agrave",     hl.dsp.window.move({ workspace = 10 }))

-- Swap active window with the neighboring window in the given direction
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+ && ~/.config/hypr/scripts/osd_volume.sh"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%- && ~/.config/hypr/scripts/osd_volume.sh"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle && ~/.config/hypr/scripts/osd_volume.sh"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+ && ~/.config/hypr/scripts/osd_brightness.sh"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%- && ~/.config/hypr/scripts/osd_brightness.sh"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- Lock screen shortcut
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("hyprlock"))

-- Launch Walt in kitty (SUPER + W)
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("kitty --class=walt -e " .. home .. "/.local/bin/walt"))

-- Apply one wallpaper at a time with a smooth fade transition (SUPER + SHIFT + W)
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd(home .. "/.config/hypr/scripts/walt-random-one-by-one.sh"))

-- Change wallpaper smoothly with Super + Space
hl.bind("SUPER + space", hl.dsp.exec_cmd("bash " .. home .. "/.config/hypr/scripts/custom/quick-switch.sh"))

-----------------------------------
---- SCREENSHOT KEYBINDINGS -------
-----------------------------------

-- 1. PrintScreen (or Fn + PrintScreen) -> Area Selection
hl.bind("Print", hl.dsp.exec_cmd([[sh -c 'grim -g "$(slurp)" - | tee ~/Pictures/Screenshots/$(date +%Y-%m-%d_%H-%M-%S).png | wl-copy']]))

-- 2. Super + PrintScreen -> Capture Full Screen
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd([[sh -c 'grim - | tee ~/Pictures/Screenshots/$(date +%Y-%m-%d_%H-%M-%S).png | wl-copy']]))

-- 3. Super + Shift + PrintScreen -> Capture Active Window
hl.bind(mainMod .. " + SHIFT + Print", hl.dsp.exec_cmd([[sh -c 'grim -g "$(hyprctl activewindow -j | jq -r "\"\(.at[0]),\(.at[1]) \(.size[0])x\(.size[1])\"")" - | tee ~/Pictures/Screenshots/$(date +%Y-%m-%d_%H-%M-%S).png | wl-copy']]))


--------------------------------
---- WINDOWS AND WORKspaceS ----
--------------------------------

-- Fix dragging issues with XWayland tooltips/popups
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})


-- Walt: open floating and centered.
-- Verify the actual class reported by hyprctl clients after first launch.
hl.window_rule({
    name  = "float-center-walt",
    match = { class = "^walt$" },

    float  = true,
    center = true,
    size   = "900 600",
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Kitty terminal: open floating, centered, at a fixed usable size.
-- Toggle back to tiled with SUPER + V.
hl.window_rule({
    name  = "float-center-kitty",
    match = { class = "^kitty$" },

    float  = true,
    center = true,
    size   = "45% 45%",
})


